// Full, resumable Ghidra export of the authenticated original Fortnite 5.41 PE.
// The script processes a deterministic range of ORIGINAL AMD64 .pdata entries.
// Every addressed native function yields one record, including failed/timeout
// attempts. The complete source dump belongs to a PRIVATE repository/branch.
//
// Usage (headless -postScript):
// Fortnite541FullDump.java OUTPUT_DIR START_INDEX COUNT TIMEOUT_SECONDS
//
// This is pseudocode generated by Ghidra, not source-equivalent C++ and not
// proof that reconstructed functions compile or behave like the original.
import ghidra.app.script.GhidraScript;
import ghidra.app.decompiler.DecompInterface;
import ghidra.app.decompiler.DecompileResults;
import ghidra.program.model.address.Address;
import ghidra.program.model.listing.Function;
import ghidra.program.model.mem.Memory;
import ghidra.program.model.mem.MemoryBlock;
import java.io.BufferedWriter;
import java.io.OutputStreamWriter;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.zip.GZIPOutputStream;

public class Fortnite541FullDump extends GhidraScript {
    private static class Extent {
        final long start;
        final long end;
        final long unwind;
        Extent(long s,long e,long u) { start=s;end=e;unwind=u; }
    }

    private static long u32(Memory mem, Address a) throws Exception {
        return Integer.toUnsignedLong(mem.getInt(a));
    }
    private static String json(String s) {
        if (s==null) return "null";
        StringBuilder b=new StringBuilder("\"");
        for(int i=0;i<s.length();i++) {
            char c=s.charAt(i);
            switch(c) {
                case '\\': b.append("\\\\"); break;
                case '"': b.append("\\\""); break;
                case '\n': b.append("\\n"); break;
                case '\r': b.append("\\r"); break;
                case '\t': b.append("\\t"); break;
                default:
                    if(c<32) b.append(String.format("\\u%04x",(int)c));
                    else b.append(c);
            }
        }
        return b.append('"').toString();
    }
    private static BufferedWriter gzip(Path file) throws Exception {
        Files.createDirectories(file.getParent());
        return new BufferedWriter(new OutputStreamWriter(
            new GZIPOutputStream(Files.newOutputStream(file),256*1024),
            StandardCharsets.UTF_8), 256*1024);
    }
    private static String hex(long n) { return String.format("0x%08x",n); }

    private List<Extent> originalPdata() throws Exception {
        Memory mem=currentProgram.getMemory();
        MemoryBlock block=mem.getBlock(".pdata");
        if(block==null) throw new Exception("Original shipping executable has no .pdata block");
        Address base=block.getStart();
        Address image=currentProgram.getImageBase();
        long count=block.getSize()/12;
        List<Extent> out=new ArrayList<>();
        Set<Long> seen=new HashSet<>();
        for(long i=0;i<count;i++){
            if (monitor.isCancelled()) break;
            Address entry=base.add(i*12);
            long begin=u32(mem,entry);
            long end=u32(mem,entry.add(4));
            long unwind=u32(mem,entry.add(8));
            if(begin>=end || end-begin>10_000_000L) continue;
            Address start=image.add(begin);
            Address stop=image.add(end-1);
            if (!mem.contains(start)||!mem.contains(stop)) continue;
            if (seen.add(begin)) out.add(new Extent(begin,end,unwind));
        }
        Collections.sort(out,Comparator.comparingLong(x->x.start));
        return out;
    }

    private void manifest(List<Extent> all, Path dest) throws Exception {
        Path part=Paths.get(dest.toString()+".part");
        try(BufferedWriter out=gzip(part)){
            for (int i=0;i<all.size();i++){
                Extent e=all.get(i);
                out.write("{\"index\":"+i+",\"rva\":"+json(hex(e.start))+
                    ",\"end_rva\":"+json(hex(e.end))+
                    ",\"unwind_rva\":"+json(hex(e.unwind))+
                    ",\"bytes\":"+(e.end-e.start)+"}\n");
            }
        }
        Files.move(part,dest,StandardCopyOption.REPLACE_EXISTING);
    }

    private String references(Function fn) {
        try {
            int called=fn.getCalledFunctions(monitor).size();
            int callers=fn.getCallingFunctions(monitor).size();
            return ",\"callees_count\":"+called+",\"callers_count\":"+callers;
        } catch (Exception e) {
            return ",\"reference_error\":"+json(e.toString());
        }
    }

    @Override
    public void run() throws Exception {
        String[] args=getScriptArgs();
        if(args.length!=4){
            throw new IllegalArgumentException(
                "expected OUTPUT_DIR START_INDEX COUNT TIMEOUT_SECONDS");
        }
        Path base=Paths.get(args[0]);
        int begin=Integer.parseInt(args[1]);
        int count=Integer.parseInt(args[2]);
        int timeout=Integer.parseInt(args[3]);
        if(begin<0||count<1||count>10000||timeout<1||timeout>120)
            throw new IllegalArgumentException("invalid bounded export parameters");
        Files.createDirectories(base.resolve("functions"));
        List<Extent> pdata=originalPdata();
        if(pdata.size()<150000){
            throw new IllegalStateException(
                "Unexpected original .pdata coverage "+pdata.size()+
                "; refusing to label this incomplete input a full game dump");
        }
        if(begin==0){
            manifest(pdata,base.resolve("pdata_index.jsonl.gz"));
        }
        int end=Math.min(pdata.size(),begin+count);
        if(begin>=pdata.size())throw new IllegalArgumentException(
            "start index beyond original .pdata");
        String file=String.format("functions/pdata_%06d_%06d.jsonl.gz",begin,end-1);
        Path dest=base.resolve(file);
        Path part=Paths.get(dest.toString()+".part");
        DecompInterface dec=new DecompInterface();
        dec.toggleCCode(true);
        dec.toggleSyntaxTree(true);
        dec.setSimplificationStyle("decompile");
        if(!dec.openProgram(currentProgram)){
            throw new IllegalStateException("Ghidra decompiler could not open original PE");
        }
        int success=0,fail=0,missing=0,seeded=0;
        Address image=currentProgram.getImageBase();
        long timestamp=System.currentTimeMillis();
        try(BufferedWriter out=gzip(part)){
            for(int i=begin;i<end;i++){
                if(monitor.isCancelled()) throw new InterruptedException("Ghidra export cancelled");
                Extent e=pdata.get(i);
                Address entry=image.add(e.start);
                Function f=currentProgram.getFunctionManager().getFunctionAt(entry);
                if(f==null){
                    try {
                        disassemble(entry);
                        f=createFunction(entry,null);
                        if(f!=null)seeded++;
                    }catch(Exception error){
                        // Write an explicit failure below; do not erase the
                        // source original .pdata function from the inventory.
                    }
                }
                String status="missing_function",source=null,error=null;
                String name=null,signature=null;
                String refs="";
                if(f!=null){
                    name=f.getName();
                    try{signature=f.getSignature().toString();}catch(Exception ex){}
                    DecompileResults decompiled=dec.decompileFunction(f,timeout,monitor);
                    if(decompiled.decompileCompleted() &&
                       decompiled.getDecompiledFunction()!=null){
                        source=decompiled.getDecompiledFunction().getC();
                        status="decompiled";
                        success++;
                    }else{
                        status="decompiler_failed";
                        error=decompiled.getErrorMessage();
                        fail++;
                    }
                    refs=references(f);
                }else {
                    missing++;
                    error="No valid function created at original .pdata start";
                }
                String line="{\"index\":"+i+
                    ",\"rva\":"+json(hex(e.start))+
                    ",\"end_rva\":"+json(hex(e.end))+
                    ",\"name\":"+json(name)+
                    ",\"signature\":"+json(signature)+
                    ",\"status\":"+json(status)+
                    ",\"error\":"+json(error)+
                    ",\"c\":"+json(source)+refs+"}\n";
                out.write(line);
                if ((i-begin+1)%100==0) {
                    out.flush();
                    println("FORTNITE541_GHIDRA_BATCH_PROGRESS index="+(i+1)+
                        " / "+end+" success="+success+" failed="+fail+
                        " missing="+missing+" seeded="+seeded);
                }
            }
        }finally{dec.dispose();}
        Files.move(part,dest,StandardCopyOption.REPLACE_EXISTING);
        String summary="{\"original_pdata_functions\":"+pdata.size()+
            ",\"batch_start\":"+begin+",\"batch_end_exclusive\":"+end+
            ",\"decompiled\":"+success+",\"decompiler_failed\":"+fail+
            ",\"missing\":"+missing+",\"seeded\":"+seeded+
            ",\"elapsed_ms\":"+(System.currentTimeMillis()-timestamp)+
            ",\"file\":"+json(file)+"}\n";
        Files.writeString(base.resolve("last_batch.json"),summary,StandardCharsets.UTF_8);
        println("FORTNITE541_GHIDRA_BATCH_COMPLETE "+summary.trim());
    }
}